# dss-deploy/nas/setup/74-build.sh — 일흔째 배포 · 이미지 굽기 (2026-11-26)
#
# 🔵 **배포 회차와 파일 번호가 어긋나는 것은 이 저장소에서 원래 그렇다** —
#    66번이 예순두째, 67번이 예순세째, 68번이 예순네째, 69번이 예순다섯째,
#    70번이 예순여섯째, 71번이 예순일곱째, 72번이 예순여덟째, 73번이 예순아홉째였다.
#    (56번은 2026-11-11 의 **양식 전용**이라 회차를 안 먹었다.)
#
# 🔴 **NAS 에서 돌리는 스크립트가 아니다.** 개발 PC 의 **Git Bash** 에서 돈다.
#    NAS 에 접속하지 않는다. ssh 도 scp 도 한 줄 없다.
#
# ══════════════════════════════════════════════════════════════════════
# 🔴🔴 **맨 먼저 — 어느 판을 왜 베꼈는가** (지난 판 일곱이 전부 이 줄을 적었다)
# ══════════════════════════════════════════════════════════════════════
#   이 파일은 **73-build.sh(예순아홉째 · 2026-11-26)를 복사해 값만 고친 것**이고,
#   **마이그레이션과 묶음을 다루는 자리는 71-build.sh(예순일곱째 · 2026-11-25)에서
#   되살린 것**이다 (2026-11-19 결정 — 「배포본은 복사하고 값만 고친다. 검사는
#   하나도 안 뺀다. diff 가 곧 검수다」).
#   🔴 **그래서 이 파일을 검수하는 길은 「diff 73-build.sh 74-build.sh」 와
#      「diff 71-build.sh 74-build.sh」 둘이다.** 앞의 것이 「값이 맞게 바뀌었나」를,
#      뒤의 것이 「묶음 꼴을 제대로 가져왔나」를 보여 준다.
#
#   ── 🔴 73번과 **다른 것 다섯** ───────────────────────────────────────
#        | 73번(예순아홉째)      | 74번(이번)
#     집  | 둘(A/S + 재고)        | 🔴 **하나**(A/S)
#     굽는 것| 이미지 4            | 🔴 **이미지 2**(앱 1 + 도구 1)
#     마이그| 0건(양쪽 다)         | 🔴🔴 **1건**(A/S 134 → **135**)
#     서브모듈| **안 움직인다**      | 🔴🔴 **움직인다**(dss-core 191676f → a464752)
#     묶음 | 없음                  | 🔴🔴 **있다**(as-migrations.tar.gz · 135장)
#
#   ── 🔴🔴 **71-build.sh 에서 되살린 것 여덟 — 한 벌이다** ─────────────
#   73번은 마이그레이션이 0건이라 그 자리를 통째로 비워 두고 「왜 없는가」에
#   「71번에서 되살려라」를 적어 두었다. **그 날이 이번**이다. 되살린 것:
#     ① **MIGTAR 변수**(산출물 폴더 안 as-migrations.tar.gz 의 자리)
#     ② **migtar_inside()** — 묶음 **안**을 세는 함수(--go 와 --verify 가 함께 쓴다)
#     ③ **묶음을 실제로 만드는 절** — 71번에서는 「다섯째 산출물」이었고
#        이 판에서는 이미지가 둘이라 **「셋째 산출물」**이다(하는 일은 같다)
#     ④ **--verify 의 묶음 절** — 다시 만들지 않고 **열어서만** 재어 지문을 찍는다
#     ⑤ **DESTRUCTIVE_RE · SQL_COMMENT_RE · MIG_DROP_WANT** 와 **4-ㄱ 의 잣대 표본**
#     ⑥ **AS_NEW_MIGS · AS_NEW_MIGS_WANT** (이번 판이 올릴 번호 목록)
#     ⑦ **AS_KEEP_MIGS**(창 안) 와 **4-ㄹ 절** — .sql 과 스냅샷이 짝인가
#     ⑧ **3절의 「서브모듈이 움직였는가」 꼴** — 73번은 「되감기지 않았는가」였다
#   🔴 **하나만 되살리면 안 된다.** ①②③ 이 한 벌이고, ⑤ 가 없으면 4-ㄷ 의
#      「지우는 문장 0줄」이 **아무것도 안 재는 ✓** 가 된다. ④ 가 없으면 다시 구워야만
#      지문을 받을 수 있어 **md5 가 바뀐다.**
#
#   ── 🔴 **그 밖은 전부 73번 그대로다** ────────────────────────────────
#   73번이 71·72번에서 지켜 온 자리를 하나도 안 잃었다:
#     · TOOLS_PAYLOAD 를 **스칼라 정규식 + 잣대 표본**으로 두기(표에 | 를 안 넣는다)
#     · 「기능 표식을 코드 줄에서 따오지 않기」
#     · KO_MARKS 의 **바이트 확인 절**(1-ㄷ)
#     · inside_check 를 **굽기와 --verify 가 함께 쓰는 한 함수**로 두기
#     · 고리마다 「몇 개를 봤는가」를 끝에서 단언하기
#
# ══════════════════════════════════════════════════════════════════════
# 🔴 **이 파일에 「왜 없는가」를 적어 두는 절 셋**
#    (73·70·68·67·65·64·63 이 그렇게 했다 — 그 글이 없으면 다음 판이
#     「원래 없는 절」로 읽고, 되살려야 할 때 아무도 되살리지 않는다)
# ══════════════════════════════════════════════════════════════════════
#   ① 🔴🔴 **재고관리(dss-inventory)가 통째로 없다.** 73번에는 REPOS·IMAGES·
#      COPYRULES·APPMARKS·TOOLMARKS·INV_KEY_FILES·PUBLIC_WANT·시험 등록의 **글롭 절**
#      (5-ㅇ 의 ㄴ)·inside_check 의 **inventorytools 가지**가 있었다. 까닭: 재고는
#      **이번 범위에 한 줄도 없다** — 어제(예순아홉째)에 0.9 가 올라갔고 오늘은
#      **「안 건드리는 집」**이다.
#      🔴 재고가 다시 올라가는 판에서는 **73-build.sh 에서 통째로 되살려라.** 그때
#         되살릴 것은 표 몇 줄이 아니라 **절 다섯**이다:
#           · REPOS·IMAGES 에 집을 더하고 고리마다 「몇 집을 봤는가」 기대값 올리기
#           · COPYRULES 의 **inventory|drizzle|yes · inventory|vendor|no**
#             (🔴 A/S 와 **뜻이 정반대**인 줄이 둘이다 — 73-build.sh:699-709)
#           · 시험 등록 — 재고는 **글롭**이다(목록 파일 방식으로 착각해 빼면 그 집이
#             아무 검사도 안 받는다 · 73-build.sh:972-992 · 2010-2221 의 ㄴ 절)
#           · inside_check 의 inventorytools 가지(이미지 안 .sql **28장**이 맞다 ·
#             tests/ 는 **없는 것이 정상** · vendor 도 **없는 것이 정상**)
#           · PUBLIC_WANT 의 **넷째 칸**(재고 public/ 은 **있는데 비어 보인다**)
#      🔵 **포털(dss-auth)은 73번에도 없었다** — 그것을 되살리는 법은 71-build.sh 에
#         적혀 있다(그 집의 시험 등록은 **또 다른 셋째 방식** — package.json 의
#         test 줄에 **경로를 나열**한다).
#   ② 🔵 **「재고 도구 이미지 안 .sql 28장」을 세는 자리가 이 파일에는 없다.**
#      그 수는 **굽는 이미지**에서만 셀 수 있고 이번엔 그 이미지를 안 굽는다.
#      🔵 다만 **74-deploy.sh 의 2-ㄷ-2 는 그 절을 그대로 들고 있다** — 운영의
#         compose 가 가리키는 **어제 올린 도구 이미지**를 열어 28장을 센다(뒷걸음).
#   ③ 🔵 **괄호가 든 경로가 이번 범위에 0장이다**(73번은 1장). **대괄호는 3장**이다.
#      🔴 **그 셈을 빼지 않았다** — 67번이 0 이었는데 안 빼서 68번의 [id] 를 잡았다.
#      🔵 그래서 AS_KEY_FILES 에 **범위 밖의 괄호 경로 둘**을 그대로 두고, **범위 안의
#         대괄호 경로 하나**를 더해 길이 끊겼는지 잰다.
#
# ══════════════════════════════════════════════════════════════════════
# 🔴 **이 배포가 올리는 것 — A/S 한 집 · 세 갈래**
#    🔴🔴 **DB 가 바뀐다**(마이그레이션 **1건** · dss_as 134 → 135)
# ══════════════════════════════════════════════════════════════════════
#   ㄱ) **첨부 분류에 「DATA」 를 더한다**(c091222c). 🔴 **DB 가 바뀌는 유일한 갈래**다 —
#      0134 가 enum 「attachment_category」 에 값 하나를 **기타 앞에** 끼운다.
#      🔵 이름표가 **영문 「DATA」** 인 것은 실수가 아니다 — 연락서 폴더 안에 이미 있는
#         「DATA」 하위 폴더와 **글자가 같아야** 그 폴더로 들어간다(고치지 말 것).
#      🔴 공용 스키마(vendor/dss-core)에도 같은 값이 들어갔다 — **서브모듈이 움직인다.**
#   ㄴ) **[연락서 폴더에 저장] 창에 파일 이름을 적는 칸**(8adecea8). 기본값은 **지금
#      저장될 이름**이고, 경로 글자·감춰지는 이름·길이를 **거절**한다(치환이 아니다).
#   ㄷ) **[파일 올리기]의 칸이 「파일 이름」에서 「폴더 이름」으로 바뀐다**(158d6211 ·
#      **마지막 커밋**). 적으면 분류 폴더 **아래에 그 이름의 폴더**를 만들고 그 안에
#      넣는다. 🔴 **파일 이름을 정하는 기능은 이날 거뒀다** — upload-file-name.ts 와
#      그 시험이 **통째로 지워졌다**(지운 파일 **2장**).
#
#   🔵 **나머지 한 커밋(de818843)은 현황판 HTML 한 장짜리**라 **이미지에 자취가 없다**
#      [실측 2026-11-26 · git show --name-only] — 71·73번이 겪은 그 꼴이다. 2절의
#      커밋 수가 ⚠️ 로 어긋나도 5-ㅁ 의 파일 수가 함께 어긋나지 않으면 그것일 수 있다.
#
#   🔴🔴 **drizzle 는 밀린 마이그레이션을 한 트랜잭션에 넣는다.** 이번에 밀린 것은
#      **0134 하나뿐**이고, 그 SQL 은 「ALTER TYPE … ADD VALUE」 **한 줄**이며 **같은
#      판에서 그 값을 쓰지 않는다**(INSERT 도 UPDATE 도 없다). 🔵 그래서 「새 enum 값을
#      같은 트랜잭션에서 쓰면 쪼개도 멈춘다」는 함정에 **이번에는 안 걸린다.**
#      🔴 다음 판에서 0135 가 그 값을 쓰면 **그때는 걸린다** — 이 문단을 그때 다시 읽어라.
#
# ══════════════════════════════════════════════════════════════════════
# 🔴 **73번의 전제 중 이번에 깨지는 것 아홉 — 하나씩 재서 뒤집었다**
# ══════════════════════════════════════════════════════════════════════
#   ① 🔴 **집이 하나다**(73번은 둘). 굽는 것이 **넷 → 둘**이고 2·3·5절의 고리가
#      **한 바퀴**만 돈다. 🔴 「몇 집을 봤는가」 관문의 기대값도 **1**(이미지는 **2**)다.
#      🔴🔴 **집이 하나면 「고리가 한 바퀴만 돌았다」가 티가 안 난다** — 73번에서는
#         그 결함이 바로 드러났다. 🔴 **그래서 관문을 하나도 안 뺐다.** 다음에 집이
#         둘이 되는 날 그 관문이 일한다.
#
#   ② 🔴🔴 **마이그레이션이 1건이다**(73번은 0건). [실측 2026-11-26 · 기준 b281ff9b]
#      저장소 .sql **135장** · journal idx **135**(마지막 **0134**) · **0135 는 없다** ·
#      이번 범위의 drizzle/ 변경 **3줄**(0134_moaning_chimera.sql ·
#      meta/0134_snapshot.json · meta/_journal.json).
#      🔴 그래서 **묶음을 만들고** 74-deploy.sh 에는 **--migrate 가 되살아난다**
#         (73번에는 그 자리가 --tools 였다).
#      🔴 A/S 는 .sql 이 **볼륨**에서 돈다(/volume1/dss/as-migrations) — 도구 이미지
#         안은 **0장**이어야 한다(5절이 값으로 잰다). **묶음을 안 보내면 적용이 0건으로
#         조용히 끝나고 겉으로는 성공으로 보인다.**
#      🔵 4-ㄴ 이 「마지막 번호가 아직 있는가」와 「다음 번호가 안 생겼는가」를
#         **같은 줄에서 함께** 센다 — 70번이 AS_NEXT_MIG 가 한 칸 빗나가 **두 판 연속
#         아무것도 안 막은** 것을 잡아낸 뒤로 생긴 규율이다.
#
#   ③ 🔴🔴 **0134 는 칸을 안 더한다 — enum 값을 더한다.**
#      [실측] 「ALTER TYPE "public"."attachment_category" ADD VALUE 'DATA' BEFORE 'OTHER';」
#      🔴 **71번의 4-ㄷ 는 「ADD COLUMN 이 1줄 이상」을 못 박았다** — 그대로 베끼면
#         **멀쩡한 마이그레이션이 ✗** 가 된다. 그래서 과녁을 **ADD VALUE** 로 바꾸고,
#         **ADD COLUMN 은 「0 이어야 한다」로 같은 줄에서 함께** 센다(한쪽만 재면
#         번호가 빗나가도 통과한다 — 이 저장소의 규율).
#      🔴 4-ㄱ 의 잣대 표본도 **여덟로 늘렸다** — 71번의 일곱에 **「ADD VALUE 를 안
#         세는가」**(이번 판의 실물)를 더했다. 🔵 71번이 일곱째(ON DELETE restrict)를
#         그렇게 더했고, **그 일곱을 하나도 안 뺐다.**
#
#   ④ 🔴🔴 **서브모듈이 움직인다**(73번은 안 움직였다 — 3절의 뜻이 **뒤집힌다**).
#      [실측 2026-11-26] A/S 의 vendor/dss-core **191676f → a464752**
#      (커밋 **1** · 파일 **1** — src/schema/attachments.ts) ·
#      A/S 의 vendor/dss-ui **1210d112 그대로** ·
#      이번 범위의 vendor/ · .gitmodules 변경 **1줄**(73번은 0줄이었다).
#      🔵 **서브모듈이 둘이다**(73번은 셋이었다 — 셋째가 재고의 dss-ui 였다).
#      🔴 **「예순일곱째가 더한 칸 넷이 아직 있는가」 절(3-ㄹ)은 그대로 뒀다** — 뜻이
#         「뒷걸음」인 채 그대로이고, 거기에 **「이번 판이 더한 것이 들어왔는가」(3-ㅁ)**를
#         새로 붙였다. 🔴 **지우지 않았다** — 지우면 되감긴 날 아무도 못 잡는다.
#
#   ⑤ 🔴 **바뀐 파일이 한 집에만 있다.** [실측 2026-11-26 · 기준 b281ff9b]
#      A/S 전체 **37** = src/ **30** + scripts/ **2** + drizzle/ **3** + vendor **1**
#            + 현황판 HTML **1**
#            · 새 **9** · 🔴 **지움 2** · 괄호 **0** · 대괄호 **3** · 시험 **16**
#      🔴🔴 **지운 파일이 2장이다**(73번은 0장) — upload-file-name.ts 와 그 시험이다.
#         🔵 CHANGED 표의 **지움 칸만 ✗ 를 낸다**(나머지는 ⚠️ 다) — 그 수가 틀리면
#            **없어졌어야 할 것이 남아 있거나, 남아야 할 것이 없어진 것**이다.
#      🔵 **tools 가 담는 것은 37 중 33**(src 30 + scripts 2 + vendor 1).
#         빠지는 넷은 **drizzle/ 3장**(🔴 묶음으로 간다 — 이미지로는 안 간다)과
#         **현황판 HTML 1장**(어느 COPY 에도 안 걸린다 — 71·73번이 겪은 자리)이다.
#         🔴 **그 차이를 결함으로 읽지 마라.**
#
#   ⑥ 🔴 **기능 표식이 넷이고 전부 한글이다**(73번은 집마다 ASCII 가 하나씩 있었다).
#      [실측 2026-11-26 · 기준판 git grep 과 지금 grep 을 둘 다 쟀다 · src/ 안 파일 수]
#        폴더 이름 (선택)                 기준 **0** → 지금 **8**파일  (158d6211 · **마지막 커밋**)
#        폴더 이름에 경로 글자             기준 **0** → 지금 **1**파일  (158d6211 · 거절 글귀)
#        확장자는 원본과 같게 유지됩니다   기준 **0** → 지금 **1**파일  (8adecea8 · 창의 안내)
#        파일 이름에 경로 글자             기준 **0** → 지금 **1**파일  (8adecea8 · 거절 글귀)
#      🔴🔴 **ASCII 기능 표식이 하나도 없다** — 이번 범위가 더한 코드에 **새 ASCII
#         문자열 리터럴이 없다.** 🔵 그래서 **ASCII 대조는 뒷걸음 쪽이 맡는다**
#         (return-candidates · shareDocRelativePath). 한글만 0 이고 그 둘이 ≥1 이면
#         그것 자체가 「한글 grep 이 깨진 것」이라는 증거다(1-ㄷ 절을 먼저 보라).
#      🔴 **ㄱ 갈래(DATA)에는 번들 표식이 없다.** 그 갈래가 더한 리터럴은
#         「DATA: "DATA"」 뿐인데, **minify 가 공백을 지워** 번들에서는 「DATA:"DATA"」 가
#         된다 — 소스 꼴로 grep 하면 **멀쩡한 번들에서 0** 이다. 🔴 그래서 그 갈래는
#         **도구 이미지 표식**(TOOLMARKS)으로 가린다(거기는 소스가 글자 그대로다).
#         🔵 번들에는 **곁들이 둘**(공백 있는 꼴 · 없는 꼴)을 **판정 없이** 찍어 둔다 —
#            다음 판이 「그때 번들에 어느 꼴로 남았나」를 이 로그에서 읽는다.
#      🔴 **export 이름을 기능 표식으로 쓰지 않았다** — 웹팩이 production 에서 줄인다
#         (mangleExports). 71번이 **코드 줄에서 따온 글자가 번들에서 0/0** 이었던 함정이다.
#
#   ⑦ 🔴 **뒷걸음 표식이 열넷으로 늘었다**(73번은 A/S 열하나). 🔴 **73번의 기능 표식
#      셋이 그대로 내려왔다:**
#          반환 요청            예순아홉째 · 기준 8  → 지금 8   ← 🔴 **한글** · 이번에 내렸다
#          return-candidates    예순아홉째 · 기준 3  → 지금 3   ← 🔵 **ASCII 대조**가 이것이다
#          부품 신청 거두기      예순아홉째 · 기준 1  → 지금 1   ← 🔴 **한글** · 이번에 내렸다
#          NO_WAITING_REPAIR_STEP        예순여덟째 · 기준 3  → 지금 3
#          shareDocRelativePath          예순일곱째 · 기준 36 → 지금 36
#          도번 / 비고                   예순여섯째 · 기준 1  → 지금 1   ← 🔴 **한글**
#          hasLiveApproval               예순네째   · 기준 4  → 지금 4
#          domesticOrders.completedEdit  예순세째   · 기준 12 → 지금 12
#          faultTags                     예순두째   · 기준 13 → 지금 13
#          radiogroup                    예순한째   · 기준 2  → 지금 2
#          "ORDER_ISSUED"                예순째     · 기준 2  → 지금 2
#          domestic-order-status-filter  쉰아홉째   · 기준 3  → 지금 3
#          portal_approval_delegations   쉰여덟째   · 기준 26 → 지금 26
#          domesticOrders.view           쉰여섯째   · 기준 17 → 지금 17
#      🔴 **셋을 다 내린 까닭**: 73번은 「같은 갈래를 가리키는 둘 중 하나면 족하다」고
#         하나만 내렸는데, 이번에는 **셋이 서로 다른 것을 지킨다** — 한글 둘은 KO 경계를
#         재는 데 쓰이고, ASCII 하나는 **대조**에 쓰인다. **하나도 뺄 자리가 없다.**
#      🔵 **번들에서 ≥1 임이 이미 확인된 것들**: 71번이 구운 번들에서 뒷걸음 아홉을
#         세어 두었다(shareDocRelativePath **23** · 도번 / 비고 **2** 등).
#         🔵 73번의 기능 표식 셋과 NO_WAITING_REPAIR_STEP 은 번들 수가 안 적혀 있지만,
#            **73·72번이 그것을 기능 표식으로 두고 --preload 를 지나 --go 까지 갔으므로**
#            dss-as:6.4 · 6.3 번들에서 **≥1 이었다**(0 이었으면 그 모드가 거기서 멈춘다).
#         🔴 **뒷걸음이 0 이면 진짜 결함이다.**
#
#   ⑧ 🔴 **도구 표식이 넷이고 전부 A/S 한 집 것이다**(73번은 집마다 둘씩 넷이었다).
#      [실측 2026-11-26 · 그 파일 안에서 센 줄 수 · 기준판에도 있던 파일만 골랐다]
#        · DATA: "DATA"            in src/lib/domain/attachment-category.ts              기준 **0** → 지금 **1**
#        · checkContactFolderSaveFileName
#                                  in src/components/repair-cases/files/ShareDocFolderPickerDialog.tsx
#                                                                                        기준 **0** → 지금 **2**
#        · 폴더 이름 (선택)         in src/components/repair-cases/files/FilesScreen.tsx  기준 **0** → 지금 **5**
#        · uploadFolder            in src/app/api/repair-cases/[id]/attachments/route.ts 기준 **0** → 지금 **12**
#      🔴 **넷 다 기준판에도 있던 파일**이다[실측 · git cat-file] — 새로 생긴 파일을
#         과녁으로 삼으면 「기준 0줄」이 **파일이 없어서 0** 인 것이라 아무것도 안 가른다.
#      🔴 **세 갈래를 다 가린다** — ㄱ(DATA) · ㄴ(파일 이름 칸) · ㄷ(폴더 이름 칸, 화면과
#         통로 양쪽). 🔵 넷째 과녁은 **대괄호가 든 경로**라 이미지 안에서도 글롭 잣대가 된다.
#
#   ⑨ 🔴🔴 **지운 파일이 이미지에서도 사라졌는가를 잰다**(73번에는 그 절이 없었다 —
#      거기는 지운 파일이 0장이었다). 🔴 **「있는가」만 재는 검사는 지우는 판을 못 막는다** —
#      upload-file-name.ts 가 이미지에 남아 있으면 **옛 소스를 구운 것**이다.
#      🔵 그래서 TOOLMARK_GONE 둘을 **「없어야 한다」**로 묻고, 바로 옆에서 **새 이름의
#         파일이 있는가**를 같은 줄에서 함께 센다.
#
# ── 돌리는 법 (개발 PC · PowerShell 에서 Git Bash 를 부른다) ──────────
#     cd "C:/Users/희만/Desktop/Development/dss-deploy/nas/setup"
#     & "C:\Program Files\Git\bin\bash.exe" ./74-build.sh --check
#     & "C:\Program Files\Git\bin\bash.exe" ./74-build.sh --go
#
#   🔴 **bash.exe 만 치면 WSL 이 잡힌다**(2026-11-04 에 걸렸다). WSL 에서 돌면
#      도커가 안 보이고 git 이 줄바꿈 때문에 **유령 diff** 를 내어 ✗ 가 흩어져
#      난다. 단서는 로그의 뿌리 경로가 **/mnt/c/…** 인 것이다 — 0절이 값으로 잰다.
#   🔴 **스크립트에 건네는 경로에는 역슬래시를 쓰지 않는다.** 역슬래시를 주면
#      bash 가 그것을 먹어 "C:Users희만Desktop…" 이 되어 No such file 이 난다.
#
#   둘째 인자로 산출물을 둘 폴더를 바꿀 수 있다(기본값은 Development/_images-74):
#     & "C:\Program Files\Git\bin\bash.exe" ./74-build.sh --go "/d/배포본/_images-74"
#
#   🔴 **docker build 와 docker save 는 이 스크립트가 직접 친다.** 대화 세션의
#      명령 분류기가 그 둘을 막으므로, **사람이 이 파일을 돌려야** 한다.
#      이 파일을 쓴 쪽은 **한 번도 굽지 않았다** — 재기만 했다.
#
# ── 이번에 굽는 것 — **이미지 둘 + 묶음 하나** ───────────────────────
#     ① A/S 앱    dss-as:6.4            → dss-as:6.5              커밋 4
#     ② A/S 도구  dss-as-tools:31       → dss-as-tools:32         🔴 --target tools
#     ③ 🔴🔴 **묶음** as-migrations.tar.gz (**135장**) → setup/incoming/
#   🔴 **묶음을 빠뜨리는 것이 이번 판의 가장 큰 위험이다.** A/S 도구의 /app/drizzle 은
#      **비어 있고**(5절이 값으로 잰다) 운영에서는 거기에 /volume1/dss/as-migrations 가
#      붙는다 — 0134 는 **이 묶음으로만** 간다. 안 보내면 db:migrate 가 **0건으로
#      조용히** 끝나고 겉으로는 성공으로 보인다(31·39번이 겪었다).
#   🔴🔴 **incoming 에 2026-11-25 의 옛 묶음이 아직 남아 있다**(71번이 보낸 **134장**짜리 ·
#      **2,680,441바이트** · md5 **8b7e8be4822e78094fa4441b5804df78**).
#      🔴 **이번 묶음은 그것보다 커야 하고 md5 가 달라야 한다** — 4-ㅁ 과 74-deploy.sh 의
#         3-ㄴ 이 **그 값을 들고 있다가 같으면 ✗ 를 낸다.** 「보냈다」고 착각하는 일을
#         **지문으로** 가른다(쉰여섯째·쉰일곱째가 **두 판 연속** 옛 묶음을 보냈다).
#   🔴 **나머지 여덟 집은 안 굽는다** — 이번 범위에 한 줄도 없다. 🔵 **재고관리도 그
#      여덟에 들어간다**(73번에서는 올라가는 집이었다).
#
# ── 🔴 태그 번호를 **지어내지 않았다** ────────────────────────────────
#   [실측 2026-11-26] nas/setup 의 **74번을 뺀 글롭**([0-9][0-9]-*.sh)을 훑어
#   가장 큰 값을 값으로 확인했다:
#     dss-as **6.4** · dss-as-tools **31**        (73-build.sh:514-519 · 73-deploy.sh:TARS)
#   🔴 **자기 자신을 세면 늘 「이미 최신」이 된다** — 글롭에서 이 판을 빼라.
#
# ── 🔴 모드 셋 ────────────────────────────────────────────────────────
#   --verify 🔴 **이미 구운 둘과 묶음을 다시 재기만 한다.** docker build 도 docker save 도
#            한 줄 안 돌리고 **묶음도 다시 안 만든다**(만들면 md5 가 바뀐다).
#            🔴 6절의 기대값이 **뒤집힌다** — 태그가 **있어야** 한다.
#   --check  재기만 한다. 아무것도 굽지 않고 아무 파일도 만들지 않는다(폴더도).
#   --go     --check 를 **먼저 그대로 돌리고**, 하나라도 ✗ 나 ? 가 있으면 멈춘다.
#            전부 ✓ 일 때만 **둘을 굽고** tar 로 뽑고 **이미지 안을 세고 묶음을 만든다.**
#   🔵 세 모드가 **같은 함수**로 잰다(check_all · inside_check · migtar_inside).
#      두 벌로 적으면 어긋난다.
#
# ── 🔴 ✓ / ✗ / ? 로 센다 ───────────────────────────────────────────────
#   ✓ 재서 맞았다   ✗ 재서 틀렸다   ? **못 쟀다**
#   🔴 ? 를 통과로 세지 않는다. 하나라도 있으면 **종료 코드 1** 이다.
#
# ── 🔴 tar 크기를 **두 번** 견준다 ────────────────────────────────────
#   ① **지난 판 tar 와** 견준다(둘 다 값이 있다 — 아래 IMAGES 표 주석).
#   ② **그 이미지 자신과** 견준다. 가지가 둘이다:
#      · containerd 저장소면 inspect .Size 가 **압축된 내용 크기**라 90~110%.
#      · 고전 저장소면 **펼친 크기**라 tar 는 그 **1/4쯤**(10~45%).
#   🔴 **tar 지문은 'docker image inspect' 의 .Id 와 맞대지 않는다.** 그것은 애초에
#      다른 값이다. 맞댈 상대는 **빌드 로그의 'exporting config sha256:'** 이다.
#
# ── 🔴 이 환경의 함정 (36~73-build.sh 에서 그대로 가져온 처방) ────────
#   ① **경로에 한글이 있다.** 모든 경로를 큰따옴표로 감싼다. 저장소 자리를 적어
#      넣지 않고 **이 파일의 자리에서 계산한다**(SCRIPT_DIR → DEV).
#   ② 🔴 **tar 가 C: 를 원격 호스트로 읽는다.** to_unix() 가 C:/… 를 /c/… 로 바꾸고,
#      docker save 와 **묶음 만들기**는 작업 폴더로 **들어가서 상대경로**로 쓴다.
#   ③ 🔵 docker build 는 개발 서버를 안 내려도 된다(.dockerignore 가 .next 를 막는다).
#   ④ 🔴 **이미지 안을 재는 명령에 한글을 넣지 않는다**가 이 판에는 **거짓**이다 —
#      🔴🔴 **표식 여덟이 한글이다**(73번은 여섯). 기능 표식 **넷이 전부 화면·거절 글귀**다.
#      그래서 70번의 **바이트 확인 절(1-ㄷ)**이 그대로 있고, **더 중요해졌다** —
#      경계가 깨지면 **기능 표식 넷이 한꺼번에 ✗** 가 난다.
#      🔵 **ASCII 대조는 뒷걸음 쪽**(return-candidates · shareDocRelativePath)이 맡는다.
#   ⑤ 🔵 **이번 범위에는 괄호가 든 경로가 0장이고 대괄호가 3장이다**(머리말 「왜 없는가」 ③).
#      🔴 목록을 넘기는 길은 **here 문서 + while read** 와 **grep -Fx** 로만 썼고,
#      컨테이너 안에서도 **set -f** 로 글롭을 끈다. **잣대 세 장**(범위 밖 괄호 둘 ·
#      범위 안 대괄호 하나)을 넣어 그 길이 살아 있는지 잰다.
#      🔵 대괄호 폴더의 시험이 조용히 안 돈 적이 이 저장소에 있다 — 거기서 온 규율이다.
#      🔴🔴 **시험 목록 파일에서는 대괄호를 「*」 로 적는다** — 이번 범위에 **그 실물이
#         하나 있다**(share-docs/contact-folder/route-source.test.ts). 실제 경로로 묻는
#         자리(이미지 안 [ -f ])와 **꼴이 다르다** — 5-ㅇ 이 둘을 갈라서 잰다.
#   ⑥ 🔴 **grep -c 는 센 값이 0 일 때 종료 코드 1 을 낸다.** 뒤에 「|| echo ?」 같은
#      안전망을 달면 **하필 바라던 0 에서만** 그것이 터져 값이 "0 ?" 가 된다.
#      이 파일은 그 꼴을 **한 군데도 쓰지 않는다** — 「$( … || true )」 로 받는다.
#   ⑦ 🔴 **tar | grep -q 를 if 에 바로 물리지 않는다.** set -uo pipefail 아래서
#      grep -q 가 먼저 끝나면 앞의 tar 가 SIGPIPE 로 죽어 **파일이 있을 때 오히려
#      ✗** 가 난다. 🔴🔴 **이번 판은 묶음을 읽는다** — tar 를 읽는 자리는 **전부
#      세어서 담는 꼴**(grep -c · grep -o)로만 적었다.
#   ⑧ 🔴 **CRLF.** 이 저장소들의 작업본은 전부 CRLF 다. Git Bash 의 grep 만 \r 를
#      걷어내고 리눅스 컨테이너의 GNU grep 은 안 걷어낸다. 줄 전체로 맞대는
#      검사(-Fx)는 **읽자마자 tr -d 로 \r 를 걷어낸 뒤** 맞댄다.
#   ⑨ 🔴 **빈 결과는 삼켜진 오류일 수 있다.** 목록을 읽는 자리는 **읽은 줄 수를
#      함께 받아** 너무 적으면 ✗ 로 세고, **없는 경로 하나를 일부러 함께 묻는다.**
#   ⑩ 🔴 **bash 의 $(( )) 는 0 으로 시작하는 수를 8진수로 읽는다** — 0134·0135 를
#      셈에 넣지 않는다. 번호는 **글자로** 적어 두고 글자로 맞댄다.
#   ⑪ 🔴 **Git Bash 가 docker.exe 에 넘기는 「/ 로 시작하고 빈칸 없는」 인자를
#      윈도우 경로로 번역한다.** [실측 2026-11-18] 그것 하나로 **가짜 ✗ 일곱**이 났다.
#      처방 셋을 **다 쓴다**: dockr() 로 **docker 를 부를 때만** 끄고 ·
#      **그것이 정말 꺼졌는지 값으로 재고**(1-ㄴ) · 파일 경로는 **상대로 넘긴다.**
#      🔴 **전역 export 로 끄면 git 이 깨진다 — 실제로 깨뜨려 봤다**(✗ 스물한 개).
#   ⑫ 🔴 **stdin 을 빨아들이는 명령을 고리 안에서 부르면 고리가 한 바퀴만 돈다.**
#      처방 둘을 **함께**: **-i 를 떼고**, **함수 정의에 </dev/null 을 붙인다.**
#      🔴 그리고 **「몇 개를 봤는가」를 고리마다 세어 끝에서 단언한다.**
#      🔵 이번 판은 집이 하나라 「한 바퀴만 돌아도」 티가 안 난다 — 🔴 **그래서
#         관문을 더 꼼꼼히 남겼다.** 집이 둘이 되는 날 그 관문이 일한다.
#   ⑬ 🔴 **기대값이 틀릴 확률이 배포만큼 높다.** ✗ 가지마다 doubt() 가 「검사를
#      먼저 의심하라」를 찍는다. ✓ 쪽 오판은 **영영 안 드러난다.**
#
# ── 🔴 bash -n 이 못 잡는 둘 — 이 파일에는 없다 ──────────────────────
#   ① 큰따옴표 안의 백틱은 명령 치환으로 읽힌다 → 이 파일에는 백틱이 **한 개도 없다.**
#   ② 읽기 전용 자리의 콜론과 꺾쇠로 빈 파일을 만드는 꼴은 ash 를 죽인다 →
#      이 파일에는 그 꼴이 **한 군데도 없다.** 빈 파일은 touch, 폴더는 mkdir.
#   🔴 19·20·21번에는 그 둘이 아직 남아 있다. **거기서 베껴 오지 마라.**
# ══════════════════════════════════════════════════════════════════════
set -uo pipefail

# ══════════════════════════════════════════════════════════════════════
# 🔴 **Git Bash 가 /app/… 을 C:/Program Files/Git/app/… 으로 바꾼다** (결함 ②)
# ══════════════════════════════════════════════════════════════════════
#   docker.exe 는 **윈도우 프로그램**이라 MSYS 런타임이 인자를 넘기기 전에
#   「유닉스 절대경로처럼 생긴 것」을 윈도우 경로로 **조용히 번역한다.** 값에
#   빈칸이 없고 / 로 시작하면 걸린다:
#
#       docker run -e F="/app/src/x.ts" …  →  컨테이너 안에서 $F 가
#       C:/Program Files/Git/app/src/x.ts  가 되어 [ -f "$F" ] 가 거짓이 된다
#
#   🔴 **전역 export 로 끄지 않는다** — git 이 깨진다. docker 를 부르는 자리에만
#      붙인다. 같은 셸에서 git 은 그대로다.
dockr() { MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*' docker "$@" </dev/null; }
# 🔵 </dev/null 은 결함 ① 의 처방이다. docker run 은 -i 가 없으면 stdin 을 안 읽지만,
#    나중에 누가 -i 를 되살려도 **고리가 살아남게** 함수 정의에 붙여 둔다.

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
DEV=${DSS_DEV:-$(cd "$SCRIPT_DIR/../../.." && pwd)}

PASS=0; FAIL=0; UNK=0
ok()   { PASS=$((PASS+1)); printf '  ✓ %s\n' "$1"; }
bad()  { FAIL=$((FAIL+1)); printf '  ✗ %s\n' "$1"; }
unk()  { UNK=$((UNK+1));   printf '  ? %s — 못 쟀다 (%s)\n' "$1" "$2"; }
note() { printf '  ⚠️ %s\n' "$1"; }
say()  { printf '    %s\n' "$1"; }
step() { printf '\n%s\n' "── $1"; }
# 🔴 ✗ 가 났을 때 그 자리에서 찍는다 — 처음 도는 코드라 기대값이 틀릴 확률이
#    굽기만큼 높다. ✓ 쪽 오판은 영영 안 드러나므로 ✗ 쪽을 크게 적는다.
doubt() { say "🔵 ✗ 가 났으면 **검사 자신을 먼저 의심하세요** — 이 줄의 기대값이"
          say "   어디서 왔는지는 이 파일 머리말에 적혀 있습니다."; }

isnum() { case "${1:-}" in (''|*[!0-9]*) return 1;; (*) return 0;; esac; }

# 🔴 C:\… 또는 C:/… 를 /c/… 로. tar 는 드라이브 문자를 원격 호스트로 읽는다.
to_unix() { # 1 경로
  local p=${1//\\//}
  case "$p" in
    [A-Za-z]:/*) p=/$(printf '%s' "${p%%:*}" | tr 'A-Z' 'a-z')${p#?:} ;;
  esac
  printf '%s' "$p"
}

tar_name() { printf '%s.tar' "$(printf '%s' "$1" | tr ':' '-')"; }

# tar 안 manifest.json 의 Config 지문 (39~70-build.sh 의 것을 글자 그대로)
tar_config_id() { # 1 tar
  tar -xOf "$1" manifest.json 2>/dev/null \
    | tr ',' '\n' | grep -o 'blobs/sha256/[0-9a-f]\{64\}' | head -1 \
    | sed 's|blobs/sha256/|sha256:|'
}

# 두 수의 차이가 몇 퍼센트인가 (정수). 0 으로 나누지 않는다.
pct_diff() { # 1 새값 2 옛값 → 퍼센트(정수). 못 재면 아무것도 안 찍는다.
  local a b d
  a=$1; b=$2
  isnum "$a" || return 1
  isnum "$b" || return 1
  [ "$b" -gt 0 ] || return 1
  if [ "$a" -ge "$b" ]; then d=$((a - b)); else d=$((b - a)); fi
  printf '%s' $((d * 100 / b))
}

# package.json 의 scripts 블록 **안**만 센다.
count_scripts() { # stdin = package.json
  awk '
    /^  "scripts": \{/ { inb = 1; next }
    inb && /^  \}/      { inb = 0 }
    inb && /^    "/     { n++ }
    END { print n + 0 }
  '
}

# 🔵 **count_test_paths() 가 없다** — 그것은 **포털 전용**이었다(package.json 의
#    「test」 줄에 경로를 나열하는 방식을 세는 함수). 이 판에는 포털이 없다.
#    🔴 포털이 다시 올라가는 판에서는 **71-build.sh:386-388 에서 되살려라** —
#       A/S 의 목록 파일 방식으로 착각해 그 절을 빼면 그 집의 시험 등록이
#       **아무 검사도 안 받는다.**

