#   🔵 **끝 SHA 는 어디에도 안 적는다** — 늘 main 을 본다(git 이 그때그때 센다).
#      그래서 커밋이 더 밀려도 **고칠 자리는 커밋 수와 파일 수뿐**이다.
#
# ── 🔴 저장소 **하나** (73번은 둘이었다) ──────────────────────────────
