as|^COPY .*vendor \./vendor|yes|🔴 A/S tools 가 vendor/ 를 담는다 — 🔴 **이번 판은 그 안이 움직였다**(3-ㅁ)
as|^COPY .*drizzle \./drizzle|no|🔴 A/S tools 는 drizzle/ 을 **안 담는다** — 볼륨이 정본이다. 🔴 **그래서 묶음을 만들어 보낸다**
