# ══ 🔴 앱 번들에서 쓸 표식 — **전부 리터럴 · 기능 넷이 다 한글** ══════
#   열쇠|갈래(feature|keep|side)|글자|사람이 읽을 말
#   🔴 **공백이 든 표식이 있고 한글이 여덟이다.**
#      그래서 이 표는 tr -d ' ' 로 읽지 않고 **here 문서 + IFS='|' read** 로만 읽는다.
#   🔴 **표식에 | 가 든 것은 하나도 없다**[값으로 확인] — 정규식을 이 꼴의 표에
#      넣었다가 깨진 자리가 따로 있다(TOOLS_PAYLOAD 의 주석).
#
#   🔴🔴 **기능 표식을 「코드 줄」에서 따오지 않았다** — minify 가 지역 이름을 갈아
#      치우고, 웹팩이 production 에서 **export 이름까지 줄인다**(mangleExports).
#      71번이 그 함정에 데었다: part.drawingNo, part.note 가 소스에는 1줄인데
#      **번들에서는 0/0** 이었다.
#   🔵 **이번 기능 표식 넷은 전부 「사람이 읽는 글자」**다 — 화면 글자 둘과 거절 글귀
#      둘이고, minify 는 문자열 **내용**을 안 바꾼다.
#   🔴🔴 **ㄱ 갈래(DATA)에는 번들 표식이 없다** — 그 갈래가 더한 리터럴이
#      「DATA: "DATA"」 뿐인데 **minify 가 공백을 지운다.** 그래서 그 갈래는 **도구
#      표식**으로 가리고(TOOLMARKS), 번들에는 **곁들이 둘**(공백 있는 꼴 · 없는 꼴)을
#      **판정 없이** 찍어 둔다. 🔵 다음 판이 「그때 어느 꼴로 남았나」를 로그에서 읽는다.
#
#   🔴🔴 **아래 수는 전부 「소스에서 센 값」이다 — 번들 수가 아니다.**
#      이 파일은 **한 번도 굽지 않았다 — 재기만 했다.** 🔴 --go 가 번들 수를
#      **처음** 찍는다. 그때 기능 표식이 0 으로 나오면 **되돌리기 전에 --verify 로
#      다시 재고 이 주석부터 보라.**
#      🔵 71번이 번들에서 실제로 센 값 중 이 판에도 쓰는 것(참고):
