#         다만 73·72번이 그것을 **기능 표식**으로 두고 --preload 를 지나 --go 까지
#         갔으므로 dss-as:6.4 · 6.3 번들에서 **≥1 이었다**(0 이었으면 거기서 멈춘다).
#         🔴 **뒷걸음이 0 이면 진짜 결함이다.**
#
